/bin/bash -lc 'tmp_dir=$(find "${TMPDIR%/}" -maxdepth 1 -type d -name '"'govt-girls-college-dausa.*' | sort | tail -1); python3 -c 'from html.parser import HTMLParser; import sys,re
class P(HTMLParser):
 def __init__(self): super().__init__(); self.intr=False; self.intd=False; self.buf=[]; self.row=[]
 def handle_starttag(self,t,a):
  if t==\"tr\": self.intr=True; self.row=[]
  elif self.intr and t==\"td\": self.intd=True; self.buf=[]
 def handle_endtag(self,t):
  if t==\"td\" and self.intd: self.intd=False; self.row.append(re.sub(r\"\\\\s+\",\" \",\"\".join(self.buf)).strip())
  elif t==\"tr\" and self.intr:
   self.intr=False
   if self.row and any(re.search(r\"Dausa|दौसा|Daus\",x,re.I) for x in self.row): print(\" || \".join(self.row))
 def handle_data(self,d):
  if self.intd: self.buf.append(d)
p=P(); p.feed(open(sys.argv[1],errors=\"ignore\").read())
' \""'$tmp_dir/govt_colleges.html"; echo '"'--- number of rows and district names containing D? ---'; rg -o '<td>["'^<]*</td>'"' \""'$tmp_dir/govt_colleges.html" | rg -i '"'Dausa|Dau|Dhol|Jaip|Kara|Sawai|Bharat|Alwar' | sed -n '1,160p'; echo '--- total rows ---'; rg -c '<tr>' \""'$tmp_dir/govt_colleges.html"'

