def load_career_nodes(database_path: Path) -> dict[int, dict[str, Any]]:
    connection = sqlite3.connect(database_path)
    connection.row_factory = sqlite3.Row
    try:
        nodes = {
            row["id"]: {
                "id": row["id"],
                "slug": row["slug"],
                "name": row["name"],
                "parent_id": row["parent_id"],
            }
            for row in connection.execute(
                "SELECT id, slug, name, parent_id FROM career_nodes"
            )
        }
    finally:
        connection.close()

    for node in nodes.values():
        names: list[str] = []
        seen: set[int] = set()
        current_id: int | None = node["id"]
        while current_id is not None:
            if current_id in seen:
                raise ValueError(
                    f"Cycle detected in career_nodes at node {current_id}"
                )
            seen.add(current_id)
            current = nodes.get(current_id)
            if current is None:
                raise ValueError(
                    f"Missing career_nodes parent referenced by {current_id}"
                )
            names.append(current["name"])
            current_id = current["parent_id"]
        node["breadcrumb"] = " > ".join(reversed(names))
    return nodes


def is_http_url(value: Any) -> bool:
    if not isinstance(value, str):
        return False
    parsed = urlparse(value)
    return parsed.scheme in {"http", "https"} and bool(parsed.netloc)

def is_official_url(url: str, domains: set[str]) -> bool:
    hostname = normalized_hostname(url)
    return any(
        hostname == domain or hostname.endswith(f".{domain}")
        for domain in domains
    )


def load_career_nodes(
    database_path: Path = DATABASE_PATH,
) -> dict[int, dict[str, Any]]:
    connection = sqlite3.connect(f"file:{database_path}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        nodes = {
            row["id"]: {
                "id": row["id"],
                "slug": row["slug"],
                "name": row["name"],
                "parent_id": row["parent_id"],
            }
            for row in connection.execute(
                "SELECT id, slug, name, parent_id FROM career_nodes"
            )
        }
    finally:
        connection.close()

    for node in nodes.values():
        names: list[str] = []
        seen: set[int] = set()
        current_id: int | None = node["id"]
        while current_id is not None:
            if current_id in seen:
                raise ValueError(f"Career-node cycle at {current_id}")
            seen.add(current_id)
            current = nodes.get(current_id)
            if current is None:
                raise ValueError(f"Missing career node {current_id}")
            names.append(current["name"])
            current_id = current["parent_id"]
        node["breadcrumb"] = " > ".join(reversed(names))
    return nodes


